-- Local test/bootstrap schema; production tables already exist.
CREATE TABLE site_settings (   key TEXT PRIMARY KEY,   value TEXT NOT NULL,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE page_content (   id TEXT PRIMARY KEY,   section TEXT NOT NULL,   content TEXT NOT NULL DEFAULT '{}',   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE skills (   id TEXT PRIMARY KEY,   title TEXT NOT NULL,   description TEXT NOT NULL DEFAULT '',   image_url TEXT,   tags TEXT NOT NULL DEFAULT '[]',   sort_order INTEGER NOT NULL DEFAULT 0,   is_published INTEGER NOT NULL DEFAULT 1     CHECK (is_published IN (0, 1)),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE projects (   id TEXT PRIMARY KEY,   title TEXT NOT NULL,   slug TEXT NOT NULL UNIQUE,   description TEXT NOT NULL DEFAULT '',   image_url TEXT,   github_url TEXT,   live_url TEXT,   tags TEXT NOT NULL DEFAULT '[]',   sort_order INTEGER NOT NULL DEFAULT 0,   is_published INTEGER NOT NULL DEFAULT 0     CHECK (is_published IN (0, 1)),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE posts (   id TEXT PRIMARY KEY,   title TEXT NOT NULL,   slug TEXT NOT NULL UNIQUE,   excerpt TEXT NOT NULL DEFAULT '',   content TEXT NOT NULL DEFAULT '',   cover_image_url TEXT,   status TEXT NOT NULL DEFAULT 'draft'     CHECK (status IN ('draft', 'published')),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   published_at TEXT );
CREATE TABLE media (   id TEXT PRIMARY KEY,   file_name TEXT NOT NULL,   object_key TEXT NOT NULL UNIQUE,   mime_type TEXT NOT NULL,   file_size INTEGER NOT NULL DEFAULT 0,   public_url TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
